// Velure — validate & normalise a booking request (never trust the client)
const b = ($input.first().json.body) || {};
const s = (v) => (typeof v === 'string' ? v.trim() : '');

const TREATMENTS = {
  'signature-glow-facial': 'Signature Glow Facial',
  'wrinkle-relaxers': 'Wrinkle Relaxers',
  'dermal-fillers': 'Dermal Fillers',
  'collagen-microneedling': 'Collagen Microneedling',
  'laser-rejuvenation': 'Laser Rejuvenation',
  'body-contouring': 'Body Contouring',
  'consultation': 'Consultation',
};
const SLOTS = ['09:00','09:30','10:00','10:30','11:00','11:30','12:00','12:30','13:00','13:30',
  '14:00','14:30','15:00','15:30','16:00','16:30','17:00','17:30','18:00'];

// Abuse guard (speed bumps for naive bots; the real fix is Turnstile / a WAF).
// 1) The browser always sends Origin; direct scripts usually do not.
// 2) The form sends how long it was open (elapsedMs); bots post instantly.
// Either failing returns the same silent "ok" as the honeypot and stores nothing.
// Add your custom domain to ORIGIN_OK when you have one.
const ORIGIN_OK = /^(http:\/\/localhost:3000|https:\/\/velure-medspa[a-z0-9-]*\.vercel\.app)$/;
const origin = String((($input.first().json.headers) || {}).origin || '');
if (!ORIGIN_OK.test(origin) || !(Number(b.elapsedMs) >= 2500)) return [{ json: { honeypot: true, valid: false } }];

// Honeypot: pretend success, store nothing
if (s(b.company)) return [{ json: { honeypot: true, valid: false } }];

const errors = {};
const treatmentId = s(b.treatmentId);
if (!TREATMENTS[treatmentId]) errors.treatmentId = 'Please choose a treatment';

// Phoenix is UTC-7 all year (no DST)
const PHX_OFFSET_MS = 7 * 3600 * 1000;
const phxToday = new Date(Date.now() - PHX_OFFSET_MS);
const ymd = (d) => d.toISOString().slice(0, 10);
const todayStr = ymd(phxToday);
const maxStr = ymd(new Date(phxToday.getTime() + 60 * 86400000));

const date = s(b.date);
if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
  errors.date = 'Please choose a date';
} else {
  const dow = new Date(date + 'T12:00:00Z').getUTCDay();
  if (dow === 0) errors.date = 'We are closed on Sundays';
  else if (date <= todayStr || date > maxStr) errors.date = 'Please choose a date between tomorrow and 60 days ahead';
}
const time = s(b.time);
if (!SLOTS.includes(time)) errors.time = 'Please choose a time';

const firstName = s(b.firstName).slice(0, 50);
const lastName = s(b.lastName).slice(0, 50);
if (!firstName) errors.firstName = 'Required';
if (!lastName) errors.lastName = 'Required';
const email = s(b.email).toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) errors.email = 'Please enter a valid email';
const phone = s(b.phone);
if (!/^[0-9+()\-\s]{7,20}$/.test(phone)) errors.phone = 'Please enter a valid phone number';
if (b.consent !== true) errors.consent = 'Please confirm to continue';
const notes = s(b.notes).slice(0, 500);
const firstVisit = b.firstVisit === true;

if (Object.keys(errors).length) return [{ json: { honeypot: false, valid: false, errors } }];

const DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const d = new Date(date + 'T12:00:00Z');
const dateLabel = `${DAYS[d.getUTCDay()]}, ${MONTHS[d.getUTCMonth()]} ${d.getUTCDate()}`;
const [hh, mm] = time.split(':').map(Number);
const timeLabel = `${((hh + 11) % 12) + 1}:${String(mm).padStart(2, '0')} ${hh < 12 ? 'AM' : 'PM'}`;
const slotKey = `${date}T${time}`;
const bookingId = `VEL-${date.replace(/-/g, '')}-${time.replace(':', '')}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`;

return [{ json: { honeypot: false, valid: true, data: {
  bookingId, treatmentId, treatmentName: TREATMENTS[treatmentId],
  date, time, slotKey, appointmentLocal: `${date}T${time}:00`,
  dateLabel, timeLabel, firstName, lastName, fullName: `${firstName} ${lastName}`,
  email, phone, firstVisit, notes, source: 'velure-web',
} } }];

// Shared Velure email shell (inline styles only — email clients ignore <style> blocks)
const shell = (title, bodyHtml) => `<!doctype html><html><body style="margin:0;padding:0;background:#FAF6F1;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#FAF6F1;padding:40px 16px;">
<tr><td align="center">
<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#FFFFFF;border:1px solid #EFE6DA;border-radius:14px;">
<tr><td style="padding:40px 40px 8px 40px;font-family:Georgia,'Times New Roman',serif;font-size:26px;letter-spacing:-0.5px;color:#2B2420;">Velure</td></tr>
<tr><td style="padding:0 40px;font-family:Helvetica,Arial,sans-serif;font-size:10px;letter-spacing:3px;text-transform:uppercase;color:#B08968;">Med Spa &middot; Scottsdale</td></tr>
<tr><td style="padding:28px 40px 0 40px;"><div style="height:1px;background:#EFE6DA;line-height:1px;">&nbsp;</div></td></tr>
<tr><td style="padding:28px 40px 0 40px;font-family:Georgia,'Times New Roman',serif;font-size:24px;line-height:1.25;color:#2B2420;">${title}</td></tr>
<tr><td style="padding:16px 40px 36px 40px;font-family:Helvetica,Arial,sans-serif;font-size:15px;line-height:1.65;color:#4A3F39;">${bodyHtml}</td></tr>
</table>
<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;">
<tr><td style="padding:20px 8px;font-family:Helvetica,Arial,sans-serif;font-size:11px;line-height:1.6;color:#8A7D74;text-align:center;">
Velure Med Spa &middot; 1200 Desert Bloom Ave, Scottsdale, AZ &middot; (480) 555-0142<br>
Velure is a fictional brand created as a demonstration project by <a href="https://thaus.co" style="color:#8A7D74;">Thaus</a>.
</td></tr></table>
</td></tr></table></body></html>`;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const row = (k, v) => `<tr><td style="padding:6px 0;color:#8A7D74;width:120px;vertical-align:top;">${k}</td><td style="padding:6px 0;color:#2B2420;">${v}</td></tr>`;

const d = $('Validate & Normalize').first().json.data;

const clientHtml = shell(
  `You're booked, ${esc(d.firstName)}.`,
  `<p style="margin:0 0 18px 0;">Thank you for choosing Velure. Your appointment is confirmed — we look forward to welcoming you.</p>
   <table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;font-size:14px;border-top:1px solid #EFE6DA;border-bottom:1px solid #EFE6DA;margin:8px 0 22px 0;">
   ${row('Treatment', esc(d.treatmentName))}
   ${row('Date', esc(d.dateLabel))}
   ${row('Time', esc(d.timeLabel) + ' (Arizona time)')}
   ${row('Reference', esc(d.bookingId))}
   </table>
   <p style="margin:0 0 12px 0;">Please arrive ten minutes early${d.firstVisit ? ' — as it is your first visit, we will begin with a short consultation' : ''}. We will send you a reminder the day before.</p>
   <p style="margin:0;">Need to change something? Simply reply to this email or call us at (480) 555-0142.</p>
   <p style="margin:22px 0 0 0;color:#2B2420;">With care,<br>The Velure team</p>`
);

const ownerHtml = shell(
  'New booking',
  `<table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;font-size:14px;">
   ${row('Client', esc(d.fullName))}
   ${row('Email', esc(d.email))}
   ${row('Phone', esc(d.phone))}
   ${row('Treatment', esc(d.treatmentName))}
   ${row('When', esc(d.dateLabel) + ' · ' + esc(d.timeLabel))}
   ${row('First visit', d.firstVisit ? 'Yes' : 'No')}
   ${row('Notes', esc(d.notes) || '—')}
   ${row('Reference', esc(d.bookingId))}
   </table>`
);

return [{ json: { ...d, clientHtml, ownerHtml,
  clientSubject: `Confirmed: ${d.treatmentName} on ${d.dateLabel}`,
  ownerSubject: `[Velure] New booking — ${d.fullName}, ${d.dateLabel} ${d.timeLabel}` } }];
